public class DS01_1 {
    //给定的字符先后顺序：数字在前，大写字母在后
    private static final String ORDER = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";

    public static void main(String[] args) {

//快速排序方法
private static void quickSort(String[] samples, int start, int end) {
    if(start >= end) {
        return;
    }
    String pivot = samples[start];
    int left = start;
    int right = end;
    while(left < right) {
        while(left < right && myCompare(samples[right], pivot) >= 0) {
            right --;
        }
        samples[left] = samples[right];
        while(left < right && myCompare(samples[left], pivot) <= 0) {
            left ++;
        }
        samples[right] = samples[left];
    }
    samples[left] = pivot;
    quickSort(samples, start, left - 1);
    quickSort(samples, left + 1, end);
}
//按照给定顺序比较两个字符串的方法
private static int myCompare(String a, String b) {
    int length = Math.min(a.length(), b.length());
    for(int i = 0; i < length; i ++) {
        int indexA = ORDER.indexOf(a.charAt(i));
        int indexB = ORDER.indexOf(b.charAt(i));
        if(indexA != indexB) {
            return indexA - indexB;
        }
    }
    return a.length() - b.length();
}

