        if(stack.isEmpty()) {
            for(int i = 0; i < teamNumber; i ++) {
                if(!nodeList.get(i).getHasGet()) {
                    stack.push(nodeList.get(i));
                    stack.getTop().setTrue();
                    break;
                }
            }
        }
        if(stack.isEmpty()) {
            System.out.println("\n找不到一条哈密顿通路！");
            System.exit(0);
        }
        int[] temp = graph[stack.getTop().getIndex()];
        ArrayList<Node> candidates = new ArrayList<>();
        for(int i = 0; i < teamNumber; i ++) {
            if(temp[i] == 1 && !nodeList.get(i).getHasGet()) {
                candidates.add(nodeList.get(i));
            }
        }
        if(candidates.isEmpty()) {
            stack.pop();
        } else {
            stack.push(candidates.get((int)(Math.random() * candidates.size())));
            stack.getTop().setTrue();
        }
    }
}

